package org.trillionnium.hepta.local;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/** Host scaffold for source-extracted production projection statements.
 * No Android APIs, phone connection, inference, or production source writes.
 * ProductionFragments.java is generated by run.py, with its
 * source ranges and hashes recorded in the result manifest.
 */
public final class ClickProjectionProbe {
    private ClickProjectionProbe() {}
    public static final class Child {
        public final String text;
        Child(String value) { text=value; }
    }
    public static final class Bounds {
        public final int left=0,top=0,right=100,bottom=40;
    }
    public static final class Node {
        public final String id,packageName,rawText,rawDescription;
        public final Child childText;
        public final Bounds bounds=new Bounds();
        public final boolean clickable,editable,enabled,password,focused;
        public final ObservedScrollActions scrollActions;
        public PersistentActionPolicy.Decision clickPolicy;
        public String text,description;
        int passwordGetterReads;
        Node(String[] p) {
            id=p[0];rawText=decode(p[1]);rawDescription=decode(p[2]);childText=new Child(decode(p[3]));
            clickable=Boolean.parseBoolean(p[4]);editable=Boolean.parseBoolean(p[5]);
            enabled=Boolean.parseBoolean(p[6]);password=Boolean.parseBoolean(p[7]);
            packageName=decode(p[8]);focused=Boolean.parseBoolean(p[10]);
            scrollActions="?".equals(p[9])?ObservedScrollActions.UNKNOWN:
                    ObservedScrollActions.observed(p[9].isEmpty()?Collections.<String>emptyList():Arrays.asList(p[9].split(",")));
        }
        public boolean isPassword() { return password; }
        public boolean isEditable() { return editable; }
        // A custom noneditable TextView may expose a nonzero raw inputType.
        // This must not create the policy's editable-field focus exemption.
        public int getInputType() { return 1; }
        public CharSequence getText() { checkPasswordRead();return rawText; }
        public CharSequence getContentDescription() { checkPasswordRead();return rawDescription; }
        private void checkPasswordRead() {
            if(password) { passwordGetterReads++;throw new AssertionError("Password body getter must not be evaluated"); }
        }
        public String label() {
            if(!text.trim().isEmpty())return text;
            if(!description.trim().isEmpty())return description;
            return childText.text;
        }
    }
    public static final class Observation {
        public final String id,packageName;
        public final List<Node> nodes;
        public final boolean nodesTruncated=false;
        Observation(String id,String pkg,List<Node> nodes) { this.id=id;packageName=pkg;this.nodes=nodes; }
    }
    /** Minimal containers only; no JSON parsing or action decision implementation. */
    public static final class JObject {
        public static final Object NULL=null;
        public final Map<String,Object> values=new LinkedHashMap<String,Object>();
        public JObject put(String key,Object value) { values.put(key,value);return this; }
        public int length() { return values.size(); }
    }
    public static final class JArray {
        public final List<Object> values=new ArrayList<Object>();
        public JArray() {}
        public JArray(int[] values) { for(int v:values)this.values.add(v); }
        public JArray(Iterable<?> values) { for(Object v:values)this.values.add(v); }
        public JArray put(Object value) { values.add(value);return this; }
        public int length() { return values.size(); }
    }
    public static final class Snapshot {
        public final JObject screen;
        public final DecisionGrammar grammar;
        Snapshot(JObject screen,DecisionGrammar grammar) { this.screen=screen;this.grammar=grammar; }
    }
    public static final class Answer {
        public final String text;
        Answer(String text) { this.text=text; }
    }
    public static final class Frame {
        public final DecisionGrammar grammar;
        public final Set<String> appPackages;
        public final ObservedTargetLabels targets;
        Frame(Snapshot snapshot,Set<String> packages) {
            grammar=snapshot.grammar;appPackages=packages;targets=grammar.targets;
        }
    }
    private static String decode(String value) { return new String(Base64.getDecoder().decode(value),StandardCharsets.UTF_8); }
    private static void require(boolean ok,String message) { if(!ok)throw new AssertionError(message); }
    private static String json(Object value) {
        if(value instanceof JObject)return json(((JObject)value).values);
        if(value instanceof JArray)return json(((JArray)value).values);
        if(value==null)return "null";
        if(value instanceof Boolean||value instanceof Number)return value.toString();
        if(value instanceof Map<?,?>) {
            StringBuilder out=new StringBuilder("{");
            for(Map.Entry<?,?> entry:((Map<?,?>)value).entrySet()) {
                if(out.length()>1)out.append(',');out.append(json(entry.getKey())).append(':').append(json(entry.getValue()));
            }
            return out.append('}').toString();
        }
        if(value instanceof Iterable<?>) {
            StringBuilder out=new StringBuilder("[");
            for(Object item:(Iterable<?>)value) { if(out.length()>1)out.append(',');out.append(json(item)); }
            return out.append(']').toString();
        }
        String text=String.valueOf(value);StringBuilder out=new StringBuilder("\"");
        for(int i=0;i<text.length();i++) {
            char c=text.charAt(i);
            if(c=='"'||c=='\\')out.append('\\').append(c);
            else if(c<32)out.append(String.format(java.util.Locale.ROOT,"\\u%04x",(int)c));
            else out.append(c);
        }
        return out.append('"').toString();
    }
    private static Map<String,Object> row(Object... values) {
        Map<String,Object> result=new LinkedHashMap<String,Object>();
        for(int i=0;i<values.length;i+=2)result.put((String)values[i],values[i+1]);return result;
    }
    private static void write(Path file,String value)throws Exception { Files.write(file,value.getBytes(StandardCharsets.UTF_8)); }
    private static Map<String,Object> descendantBoundary() {
        final String full=String.join("",Collections.nCopies(110,"x"))+" Clear history";
        ObservedChildText.Result observed=ObservedChildText.collect("parent",new ObservedChildText.Reader<String>() {
            public ObservedChildText.Metadata metadata(String node) {
                boolean parent="parent".equals(node);
                return new ObservedChildText.Metadata(true,true,parent,parent,false,false,false);
            }
            public String text(String node) { return "parent".equals(node)?"":full; }
            public String description(String node) { return ""; }
            public String identity(String node) { return node; }
            public int childCount(String node) { return "parent".equals(node)?1:0; }
            public String child(String node,int index) { return "child"; }
            public void release(String node) {}
        });
        return row("child_truncated",observed.truncated,"child_units",observed.text.length(),
                "full_raw_policy_allowed",PersistentActionPolicy.evaluate("","",full,false).allowed,
                "bounded_child_policy_allowed",PersistentActionPolicy.evaluate("","",observed.text,false).allowed,
                "source_hash_retained",!observed.sources.isEmpty());
    }
    public static void main(String[] args)throws Exception {
        Path fixtures=Paths.get(args[0]),out=Paths.get(args[1]);Files.createDirectories(out);
        List<Path> paths=new ArrayList<Path>();
        try(java.nio.file.DirectoryStream<Path> entries=Files.newDirectoryStream(fixtures,"*.tsv")) {
            for(Path p:entries)paths.add(p);
        }
        Collections.sort(paths);int nodeCount=0;
        for(Path fixture:paths) {
            List<String> lines=Files.readAllLines(fixture,StandardCharsets.UTF_8);String[] header=lines.get(0).split("\t",-1);
            List<Node> nodes=new ArrayList<Node>();
            for(int i=1;i<lines.size();i++) {
                Node node=new Node(lines.get(i).split("\t",-1));ProductionFragments.capture(node);
                require(node.passwordGetterReads==0,"No password read");nodes.add(node);nodeCount++;
            }
            Set<String> packages=new TreeSet<String>();if(!header[2].isEmpty())packages.addAll(Arrays.asList(header[2].split(",")));
            Snapshot snapshot=ProductionFragments.project(new Observation(header[0],header[1],nodes),packages);
            require(!snapshot.grammar.allowsClick(null),"Null click must deny without throwing");
            require(!snapshot.grammar.allowsClick("n99999"),"Unknown click must deny");
            try { snapshot.grammar.clickNodes.add("n99999");throw new AssertionError("Mutable click capability set"); }
            catch(UnsupportedOperationException expected) { /* Required immutable snapshot. */ }
            List<Object> policies=new ArrayList<Object>();
            List<Object> parserChecks=new ArrayList<Object>();
            for(Node node:nodes)policies.add(row("id",node.id,"allowed",node.clickPolicy.allowed,"reason",node.clickPolicy.reasonCode,
                    "display_text",node.text,"display_description",node.description,"retained_for_action_domain",
                    PromptActionDomain.requiresRetention(header[1],node.packageName,node.enabled,node.password,node.clickable,node.editable,node.scrollActions)));
            // These are syntactically valid exact observed pairs, including
            // prohibited targets. Parsing/binding alone must not authorize them.
            for(Node node:nodes) {
                String raw=json(row("reason","Inspect the current observed control","action","click",
                        "observation_id",header[0],"package",header[1],
                        "node_label",snapshot.grammar.targets.labels.get(node.id),"node_id",node.id));
                ActionDecision action=ActionDecision.parse(raw,DecisionGrammar.SCHEMA);
                ActionPolicy.validateTextDecision(action,header[1],packages,snapshot.grammar.targets);
                boolean accepted=true;
                try { ProductionFragments.validate(raw,snapshot,packages); }
                catch(ActionDecision.InvalidActionException expected) { accepted=false; }
                parserChecks.add(row("id",node.id,"syntax_parsed",true,"pair_validated",true,
                        "controller_accepted",accepted,"grammar_allows_click",snapshot.grammar.allowsClick(node.id)));
            }
            String name=fixture.getFileName().toString().replace(".tsv","");
            write(out.resolve(name+".json"),json(row("screen",snapshot.screen,"targets",snapshot.grammar.targets.labels,
                    "click_nodes",snapshot.grammar.clickNodes,"actions",snapshot.grammar.actions,"policies",policies,
                    "parser_checks",parserChecks))+"\n");
            write(out.resolve(name+".gbnf"),snapshot.grammar.text);
        }
        write(out.resolve("descendant-boundary.json"),json(descendantBoundary())+"\n");
        System.out.println("Production-fragment probe: fixtures="+paths.size()+" nodes="+nodeCount+"; phone_tested=false; native_grammar_tested=false");
    }
}
